const MARIAH_COMBAT_LINES=[
 'You were offered a way out. Now put down the weapon before loyalty to Josiah becomes your epitaph.',
 'He calls himself your protector. Ask yourself why everyone around him ends up needing protection from him.',
 'I did not survive exile to surrender this country to a frightened man and his golden chains.',
 'Look at the people standing against you. He taught you to call every witness a traitor so you would never hear the truth.',
 'This ends with his power broken. You can still lower your guns, but I will not lower mine while you threaten my people.',
 "In the Second World War, this country fought Nazi Germany alongside its allies. People endured the Blitz rather than submit to fascism. Josiah invokes their courage while building the very kind of tyranny they fought against.",
 "Britain once ruled the largest empire on Earth. That history carries suffering as well as power—but look at us now: a laughing stock abroad, governed by a man who mistakes frightening his own people for commanding the respect of the world.",
 "I remember the riots of twenty-four. David “Diesel” Busters and the Cyan Party had their answers, their accusations, their promises. Josiah used the chaos to seize power. An emergency became his excuse to make himself permanent.",
 "The Nazis demanded obedience, crushed opposition and made loyalty to a leader more important than human life. When Josiah imprisons dissenters and calls his enemies vermin, I will name the resemblance. A British flag does not make those methods less vile.",
 "He says he is saving a G7 nation. From what—accountability? Britain needs functioning institutions, trusted allies and a government that can be removed without a gunfight. I intend to save our place in the G7 without sacrificing the people who live here.",
 "Oswald Mosley! That is who Richards reminds me of—another bloody fascist wrapping himself in the flag and expecting Britain to kneel! How dare he call this patriotism? He has turned our country into his personal prison, and I will not bow to the bastard!",
 "Richards belongs beside the worst dictators in history! The arrests, the executions, the families terrified to speak—and he has the nerve to call himself our protector! Protect us from what? HIM? I am sick of his excuses. He will answer for every life he has destroyed!"
];
function finalWarPlayerFaction(){if(finalWar?.kevinSiegeRoute)return 'yellow';return finalWar?.defenseRoute?(finalWar.joinedResistance?'blue':'red'):'blue';}
function beginMariahOffer(){const w=finalWar,m=w?.mariah;if(!w?.defenseRoute||(w.mariahChoice&&!(w.mariahChoice==='refused'&&!w.lastMariahOffer&&mariahIsLastBlue()))||w.ended||!m||m.hp<=0||currentFloor!==m.floor||player.distanceTo(m.actor.position)>12||!finalWarSight(player,m.actor.position))return false;stopMariahCombatVoice();w.lastMariahOffer=mariahIsLastBlue();w.mariahChoice='pending';w.paused=true;w.holding=false;w.cinematicPointerRelease=true;keys.clear();drag=false;document.exitPointerLock?.();w.gun.visible=false;$('finalWarHUD').hidden=true;let ui=$('mariahOffer');if(!ui){ui=document.createElement('div');ui.id='mariahOffer';Object.assign(ui.style,{position:'fixed',inset:'0',zIndex:70,background:'linear-gradient(transparent 30%,#07030eef)',display:'flex',alignItems:'end',justifyContent:'center',padding:'5vh'});ui.innerHTML='<div class="cinema-top"><span>THE DEFENSE OF BRENT CROSS / A CHOICE</span></div><section class="cinema-dialogue mariah-choice-panel"><div class="mariah-speaker">MARIAH BANU</div><p class="mariah-dialogue">You do not have to fight for him. Join the Resistance. Stand with us against Josiah and the PSRM—or raise your weapon and face me.</p><div class="mariah-choices"><button id="mariahJoin">JOIN THE RESISTANCE<span>Stand with the coalition against Josiah and the PSRM</span></button><button id="mariahFight">FIGHT MARIAH<span>Remain with Josiah and oppose the coalition</span></button></div></section>';document.body.appendChild(ui);$('mariahJoin').onclick=()=>resolveMariahOffer(true);$('mariahFight').onclick=()=>resolveMariahOffer(false);}let third=$('mariahUsurp');if(!third){third=document.createElement('button');third.id='mariahUsurp';third.innerHTML='ONCE I’M DONE WITH YOU, I WILL GO AFTER JOSIAH<span>Defeat Mariah, then claim power for yourself</span>';ui.querySelector('.mariah-choices').appendChild(third);third.onclick=()=>{resolveMariahOffer(false);w.mariahChoice='usurper';gameProgress.defenseUsurperChosen=true;saveProgress();};}third.hidden=!mariahIsLastBlue();ui.style.display='flex';const look=m.actor.position.clone().add(new THREE.Vector3(0,1.55,0));camera.position.copy(look).add(new THREE.Vector3(1,.25,3.5));camera.lookAt(look);return true;}
function resolveMariahOffer(join){const w=finalWar;if(w?.mariahChoice!=='pending')return;w.mariahChoice=join?'joined':'refused';w.joinedResistance=join;w.mariahTauntAt=w.time+1;w.mariahTauntIndex=0;gameProgress.defenseJoinedResistance=join;saveProgress();for(const u of w.units){u.target=null;u.decision=0;u.path=[];u.repath=0;if(u.cast){disposeCampObject(u.cast.warning);u.cast=null;}}$('mariahOffer').style.display='none';w.paused=false;w.holding=false;w.gun.visible=true;$('finalWarHUD').hidden=false;$('finalWarPause').hidden=true;keys.clear();camera.position.copy(player).add(new THREE.Vector3(0,1.7,0));camera.rotation.set(pitch,yaw,0);w.transitionUntil=performance.now()+1000;requestLock();}
function updateMariahEncounter(){const w=finalWar;tickMariahCombatVoice();if(beginMariahOffer())return;let ui=$('mariahCombatLine');if(!ui){ui=document.createElement('div');ui.id='mariahCombatLine';Object.assign(ui.style,{position:'fixed',bottom:'26%',left:'25%',width:'50%',padding:'16px',background:'#100916ee',border:'1px solid #4974a0',color:'#eee',textAlign:'center',pointerEvents:'none',display:'none'});document.body.appendChild(ui);}if(['refused','usurper'].includes(w.mariahChoice)&&w.mariah.hp>0&&currentFloor===w.mariah.floor&&player.distanceTo(w.mariah.actor.position)<30&&w.time>=(w.mariahTauntAt||0)&&!w.mariahCombatVoice){ui.innerHTML='<div class="mariah-speaker">MARIAH BANU</div><p>'+MARIAH_COMBAT_LINES[w.mariahTauntIndex%MARIAH_COMBAT_LINES.length]+'</p>';playMariahCombatVoice(w.mariahTauntIndex++%MARIAH_COMBAT_LINES.length);const duration=Math.max(10,ui.textContent.split(/\s+/).length/2.5);w.mariahTauntAt=w.time+duration+4;w.mariahTextUntil=w.time+duration;}ui.style.display=w.mariahCombatVoice||w.time<(w.mariahTextUntil||0)?'block':'none';}
