const chambersTheme=new Audio("assets/audio/clip-56bd1f46a23e.mp3");
chambersTheme.loop=true;chambersTheme.preload="metadata";chambersTheme.volume=.38;let chambersThemeRequested=false;
function stopChambersTheme(){chambersTheme.pause();chambersTheme.currentTime=0;chambersThemeRequested=false;}
function updateChambersTheme(){const c=corneredRooms,w=finalWar,rooms=mode==="rooms"&&c&&!c.paused&&c.finale?.phase==="fight"&&c.finale.playerHP>0,siege=mode==="finalWar"&&w?.siegeRoute&&!w.paused&&!w.ended&&w.hp>0&&w.siegeBoss?.hp>0;chambersTheme.muted=muted;const bunker=mode==='pindar'&&pindar&&!pindar.paused&&pindar.encounter?.phase==='fight';if(!rooms&&!siege&&!bunker){stopChambersTheme();return;}chambersTheme.volume=(rooms&&c.finale.killTauntPending||siege&&w.siegeBoss.voice)?.18:.38;if(!chambersThemeRequested){chambersThemeRequested=true;chambersTheme.play()?.catch(()=>{});}}

function playtestDefenseEncounter(stage){if(mode!=='menu')return;playtestDefenseFinalChapter();finishDefenseIntro();const w=finalWar;w.paused=false;w.ended=false;w.holding=false;w.hp=150;w.ammo=24;keys.clear();currentFloor=0;w.onStairs=false;world.visible=true;upperWorld.visible=false;
 for(const u of w.units){if((stage==='last'&&u.faction==='blue'&&u!==w.mariah)||(stage==='power'&&u!==w.alliedJosiah)){u.hp=0;u.actor.visible=false;if(u.spectre)u.spectre.visible=false;}u.target=null;u.decision=0;u.path=[];u.repath=0;if(u.cast){disposeCampObject(u.cast.warning);u.cast=null;}}
 if(stage==='power'){w.mariahChoice='usurper';gameProgress.defenseUsurperChosen=true;updateUsurperRoute();player.copy(finalWarNearest(40,39,0));w.alliedJosiah.hp=w.alliedJosiah.maxHP;w.usurperQuoteAt=w.time;w.gun.visible=true;$('finalWarHUD').hidden=false;w.transitionUntil=performance.now()+1500;w.cinematicPointerRelease=true;}else{w.mariahChoice=null;w.lastMariahOffer=false;player.copy(w.mariah.actor.position).add(new THREE.Vector3(0,0,2));}
 yaw=stage==='power'?Math.atan2(player.x-w.josiah.position.x,player.z-w.josiah.position.z):0;pitch=0;camera.rotation.order='YXZ';camera.position.copy(player).add(new THREE.Vector3(0,1.7,0));camera.rotation.set(pitch,yaw,0);saveProgress();updateDefenseBattle();drawFinalWarMap();if(stage!=='power')beginMariahOffer();$('debugRestoreResult').textContent='Playtest: DEFENSE / '+(stage==='power'?'CLAIM POWER':stage==='last'?'MARIAH ALONE':'MARIAH’S CHOICE');}

const mariahCombatClips=["assets/audio/clip-56f5e28d74eb.mp3","assets/audio/clip-7a18322f428c.mp3","assets/audio/clip-d6870aa50b77.mp3","assets/audio/clip-bb85a9745b38.mp3","assets/audio/clip-fc35a5a426c7.mp3","assets/audio/clip-a02d005c7ace.mp3","assets/audio/clip-558316e29df3.mp3","assets/audio/clip-ef2cfa6856e3.mp3","assets/audio/clip-c77fdf870a8d.mp3","assets/audio/clip-11375743db80.mp3","assets/audio/clip-c9d0ac912f2d.mp3","assets/audio/clip-736450356ff4.mp3"].map(src=>{const a=new Audio(src);a.preload="metadata";return a;});
function stopMariahCombatVoice(){for(const a of mariahCombatClips){a.pause();a.currentTime=0;}if(finalWar){finalWar.mariahCombatVoice=null;finalWar.mariahTextUntil=0;}}
function playMariahCombatVoice(index){stopMariahCombatVoice();const w=finalWar,a=mariahCombatClips[index],v={audio:a,index,start:w.time,failed:false};w.mariahCombatVoice=v;a.muted=muted;a.play()?.catch(()=>{v.failed=true;});}
function tickMariahCombatVoice(){const w=finalWar,v=w?.mariahCombatVoice;if(!v)return;v.audio.muted=muted;const duration=Number.isFinite(v.audio.duration)?v.audio.duration:0,fallback=Math.max(10,MARIAH_COMBAT_LINES[v.index].split(/\s+/).length/2.5);if(w.ended||w.hp<=0||w.mariah.hp<=0||w.mariahChoice==='joined'||v.audio.ended||v.failed&&w.time-v.start>fallback||w.time-v.start>(duration?duration+10:120)){stopMariahCombatVoice();w.mariahTauntAt=w.time+4;}}

function finishLoyalDefenseOutro(){
 const w=finalWar;if(!w?.defenseRoute||w.ended||w.joinedResistance||w.mariahChoice==='usurper')return;
 w.ended=true;w.paused=true;w.holding=false;keys.clear();drag=false;document.exitPointerLock?.();
 stopMariahCombatVoice();stopJosiahBetrayalVoice();
 gameProgress.defenseBattleCleared=true;gameProgress.defenseLoyalEnding=true;saveProgress();
 for(const id of ['finalWarHUD','finalWarEnd','finalWarPause'])$(id).hidden=true;
 for(const id of ['mariahOffer','mariahCombatLine','josiahBetrayalLine','josiahResistanceBetrayal'])$(id)?.remove();
 w.gun.visible=false;
 const ui=document.createElement('div');ui.id='loyalDefenseOutro';
 ui.innerHTML='<div class="usurper-scroll"><p class="eyebrow">THE DEFENSE OF BRENT CROSS / EPILOGUE</p><h1>THE PRIME SECRETARY ENDURES</h1><p>Mariah Banu fell at the South Gate. The promise of her return ended beneath the cold lights of Brent Cross.</p><p>You had been offered a place beside the Resistance. You chose to remain with Josiah Richards. When the moment came, you raised your weapon for the man who had once saved your life.</p><p>The coalition had lost the Prime Minister it hoped to restore. Those still standing faced an uncertain future: continue a fractured rebellion, disappear into hiding, or submit to the government they had come to overthrow.</p><p>From the atrium, Josiah claimed victory. By morning, the broadcasts called Brent Cross a triumph over insurrection. They spoke of order restored, of loyalty rewarded, and of a nation protected by its Prime Secretary.</p><p>Outside, the country remained divided. Families waited for news. Doors stayed locked. The silence that followed was not peace.</p><p>You had secured your place beside him.<br>His rule would continue.</p><h2>THE PRIME SECRETARY ENDURES</h2></div><button id="loyalDefenseMenu">RETURN TO MAIN MENU</button>';
 document.body.appendChild(ui);$('loyalDefenseMenu').onclick=()=>menu();
}

function finishResistanceDefenseOutro(){
 const w=finalWar;if(!w?.defenseRoute||w.ended||!w.joinedResistance||w.mariahChoice==='usurper')return;
 w.ended=true;w.paused=true;w.holding=false;keys.clear();drag=false;document.exitPointerLock?.();
 stopMariahCombatVoice();stopJosiahBetrayalVoice();
 gameProgress.defenseBattleCleared=true;gameProgress.defenseResistanceEnding=true;saveProgress();
 for(const id of ['finalWarHUD','finalWarEnd','finalWarPause'])$(id).hidden=true;
 for(const id of ['mariahOffer','mariahCombatLine','josiahBetrayalLine','josiahResistanceBetrayal'])$(id)?.remove();
 w.gun.visible=false;
 const ui=document.createElement('div');ui.id='resistanceDefenseOutro';
 ui.innerHTML='<div class="usurper-scroll"><p class="eyebrow">THE DEFENSE OF BRENT CROSS / EPILOGUE</p><h1>THE FALL OF THE PRIME SECRETARY</h1><p>In the shattered atrium of Brent Cross, the golden chains finally fell silent. Josiah Richards was dead. The man who had promised to hold a nation together through fear could no longer command it.</p><p>He had found you wounded and abandoned. He had saved your life and offered you a place beside him. At the South Gate, you made a different choice. Gratitude would not bind you to his rule.</p><p>You stood with the Resistance. Together, you brought down the Prime Secretary.</p><p>His remaining forces were left without the voice that had directed them. Across the capital, orders went unanswered. Some laid down their weapons; others vanished into the confusion. The struggle to secure the country would outlast the battle that broke his power.</p><p>For the first time in years, a future beyond his regime seemed possible. Parliament could open its doors again. Families could ask what had become of the missing. The truth, buried beneath official broadcasts and whispered warnings, could begin to emerge.</p><p>But victory did not make the coalition innocent. Old betrayals and rival ambitions remained. Those who had fought together would now have to answer for their own actions. Freedom would mean little if the victors placed themselves above the law.</p><p>There would be no easy return to the country as it had been. There would be mourning, arguments, investigations, and the slow work of rebuilding trust.</p><p>When morning reached Brent Cross, it found broken glass, empty corridors, and people still alive to choose what came next.</p><p>The Prime Secretary had fallen.<br>The future no longer belonged to him.</p><h2>THE FALL OF THE PRIME SECRETARY</h2></div><button id="resistanceDefenseMenu">RETURN TO MAIN MENU</button>';
 document.body.appendChild(ui);$('resistanceDefenseMenu').onclick=()=>menu();
}

function playtestDefenseJosiah(){
 if(mode!=='menu')return;
 playtestDefenseEncounter('power');
 for(const key of ['defenseLoyalEnding','defenseResistanceEnding','newPrimeSecretaryEnding','defenseBattleCleared'])delete gameProgress[key];
 gameProgress.defenseJoinedResistance=false;saveProgress();
 $('debugRestoreResult').textContent='Playtest: TYRANT / SEIZE POWER / JOSIAH FIGHT';
}
